# -*- coding: utf-8 -*-
import sys
p='03-manuscript/arc-01/ch-04.md'
s=open(p,encoding='utf-8').read()
n=0
def rep(old,new,count=1):
    global s,n
    c=s.count(old)
    if c!=count:
        print('FAIL',c,repr(old[:70])); sys.exit(1)
    s=s.replace(old,new); n+=1

# П7 Агнис — заряд без «проверяй»
rep("— Заряд полный?\n\n— Проверяли утром.\n\n— Проверяй каждый раз.\n\n— Агнис.\n\n— Нет, ты не отмахивайся, я…\n\nОна сбилась и начала иначе.\n\n— Я серьёзно. — Она отпустила звезду. — Я знаю, как это делается. Мама заряжает такие для дежурной части, когда у них своих рук не хватает.\n\nЯ не знала этого.",
    "— Заряд полный?\n\n— Проверяли утром.\n\n— Смола светлая, значит, недавно лили. — Она отпустила звезду и сказала это с той небрежностью, с какой говорят то, чем гордятся. — Я знаю, как это делается. Мама заряжает такие для дежурной части, когда у них своих рук не хватает.\n\nЯ не знала этого.")

# П10 комментарии
rep("Она сказала это спокойно, как говорят о том, что давно обдумали.\n\n", "")
rep("Она ответила быстро и тут же отвернулась, что у неё означало смущение.", "Она ответила быстро и отвернулась.")
rep("Ей своей бумаги ждать ещё год.\n\nОна об этом не сказала.\n\nОна три декады делала мне подвеску.",
    "Ей своей бумаги ждать ещё год, и она три декады делала мне подвеску.")

# С5 кухня — вставка после «так, оказывается, делают»
old="Потом посмотрела и сказала, что так, оказывается, делают.\n\nЯ повертела янтарную в пальцах."
rep(old, "Потом посмотрела и сказала, что так, оказывается, делают.\n\n— Кромку — тем самым, — добавила Агнис. — Что мы в шестой день варили. Ты сказала, что пахнет, как у Гудрун во дворе, и открыла окно, и я потом декаду думала, что оно от сквозняка не схватится. Схватилось.\n\nЯ помнила запах. Я не помнила, что открывала окно, и не стала спорить: в тот вечер я смотрела в основном на дверь и думала, во сколько возвращается её мать.\n\nЯ повертела янтарную в пальцах.")

# С4 Элизабет: приходили двое
rep("— И не тяни. Перед следующим же выходом, а не когда вспомнишь.\n\nОна завинтила крышку на последней склянке и вытерла руки.\n\n— Спустись в подвал, — сказала Элизабет.",
    "— И не тяни. Перед следующим же выходом, а не когда вспомнишь.\n\nОна завинтила крышку на последней склянке и вытерла руки.\n\n— Приходили тут двое, дней десять назад, — сказала она, убирая тряпку. — Спрашивали, не брала ли я кого с улицы, временно. Я сказала, что не брала.\n\nОна не спросила, почему я это слушаю с таким лицом. Она вообще ничего не спросила.\n\n— Спустись в подвал, — сказала Элизабет.")

# С3 Элизабет в дверях
rep("Из лавки, так и не выйдя в прихожую, Элизабет сказала:\n\n— Сильвия.\n\n— Да.\n\n— Проверяй заряд сама.\n\n— Спрошу дату.\n\n---",
    "Из лавки, так и не выйдя в прихожую, Элизабет сказала:\n\n— Сильвия.\n\n— Да.\n\n— Ты её надела?\n\nЯ не сразу поняла, про что она.\n\n— Агнис надела, — сказала я. — Свою.\n\n— Я не про Агнис.\n\nЯ тронула шнурок под воротом. Он был на месте, и она этого не видела — из лавки в прихожую не видно шеи, — и всё-таки спросила.\n\n— Надела.\n\nИз лавки больше ничего не сказали, и свет там погас, пока я застёгивала куртку.\n\n---")

# П6 Кайр на Канатчиков — объединение
rep("— Ты сегодня в комиссии сказала про напарника. Что уведёшь и прервёшь задание.\n\n— Мне это уже отметили.\n\n— Кто?\n\n— Председатель. Сказал, что порядок слов был правильный.\n\nКайр смотрел куда-то в сторону порта.\n\n— Я бы то же самое ответил, — сказал он.\n\n— Знаю.\n\n— Ты опять предполагаешь.\n\n— Нет, — сказала я. — В этот раз знаю.\n\nОн усмехнулся, поправил папку и пошёл вниз.\n\n— Кайр.\n\nОн обернулся.\n\n— Спасибо, что ждал в коридоре.\n\n— Я не ждал, — сказал он. — Я стоял.\n\n— Три часа.\n\n— Стоять три часа проще, чем сидеть внутри. — Он пожал плечом. — Ты бы тоже стояла.\n\n— Я бы села.\n\n— Ты бы сказала, что села, — сказал Кайр и пошёл дальше.",
    "— Ты сегодня в комиссии сказала про напарника. Что уведёшь и прервёшь задание.\n\n— Председатель сказал, что записал. Я до сих пор не знаю, что это значит.\n\n— Значит, что порядок правильный, — сказал Кайр. — Обычно говорят наоборот: сначала задание, потом человека. Я бы ответил, как ты.\n\n— Знаю.\n\n— Откуда?\n\n— Ты три часа стоял у окна.\n\nОн посмотрел на меня так, будто я сказала это на авалийском, потом понял и отвернулся к порту.\n\n— Стоять проще, чем сидеть внутри, — сказал он в сторону порта, поправил папку и пошёл вниз.")

# С7 столб Хольма — между делом
rep("— Нашёл, — согласился он, не отрываясь от листа. — Вторая полка. Вы сказали правильно.",
    "— Нашёл, — согласился он, не отрываясь от листа. — Вторая полка. Вы сказали правильно. Столб у Бочарной я тоже посмотрел, заложили. Пометку снял.\n\nОн сказал это тем же голосом, что про полку, и не поднял головы, и я поняла, что продолжения не будет: он посмотрел, снял, и дело закрыто, а извинение в этот ряд не входит.")

open(p,'w',encoding='utf-8').write(s)
print('ok',n)
